var minCut = function(s) {
    const n = s.length;
    if (n === 0) return 0;

    const cuts = new Array(n + 1);
    for (let length = 0; length <= n; length++) cuts[length] = length - 1;

    for (let center = 0; center < n; center++) {
        let left = center, right = center;
        while (left >= 0 && right < n && s[left] === s[right]) {
            cuts[right + 1] = Math.min(cuts[right + 1], cuts[left] + 1);
            left--;
            right++;
        }

        left = center - 1;
        right = center;
        while (left >= 0 && right < n && s[left] === s[right]) {
            cuts[right + 1] = Math.min(cuts[right + 1], cuts[left] + 1);
            left--;
            right++;
        }
    }

    return cuts[n];
};

