class Solution:
    def minCut(self, s: str) -> int:
        n = len(s)
        if n == 0:
            return 0

        cuts = [length - 1 for length in range(n + 1)]

        for center in range(n):
            left = right = center
            while left >= 0 and right < n and s[left] == s[right]:
                cuts[right + 1] = min(cuts[right + 1], cuts[left] + 1)
                left -= 1
                right += 1

            left, right = center - 1, center
            while left >= 0 and right < n and s[left] == s[right]:
                cuts[right + 1] = min(cuts[right + 1], cuts[left] + 1)
                left -= 1
                right += 1

        return cuts[n]
